mapper.insert:
INSERT INTO cps_initial_review_event (
  task_id, issue_id, version_no, event_type, detail, operator_emp_no, created_at
) VALUES (
  #{taskId}, #{issueId}, #{versionNo}, #{eventType}, #{detail}, #{operatorEmpNo}, #{createdAt}
)

mapper.select:
SELECT e.id, e.task_id, e.issue_id, e.version_no,
       e.event_type, e.detail, e.operator_emp_no, e.created_at
FROM cps_initial_review_event e
INNER JOIN cps_issue i ON i.id = e.issue_id

    AND e.issue_id = #{issueId}
    AND e.event_type = #{eventType}
    AND e.task_id = #{taskId}
    AND i.factory = #{factory}
    AND i.area = #{area}
    AND i.category_l1_id = #{categoryL1Id}
    AND i.category_l2_id = #{categoryL2Id}
    AND e.created_at >= #{startTime}
    AND e.created_at <= #{endTime}

ORDER BY e.created_at DESC, e.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM cps_initial_review_event e
INNER JOIN cps_issue i ON i.id = e.issue_id

    AND e.issue_id = #{issueId}
    AND e.event_type = #{eventType}
    AND e.task_id = #{taskId}
    AND i.factory = #{factory}
    AND i.area = #{area}
    AND i.category_l1_id = #{categoryL1Id}
    AND i.category_l2_id = #{categoryL2Id}
    AND e.created_at >= #{startTime}
    AND e.created_at <= #{endTime}
